update public.learning_paths
set
  title = 'Operations Management',
  goal = 'Operations Management',
  summary = 'This syllabus is designed for a one-semester Operations Management course for business and supply-chain students. It develops the ability to diagnose processes, make quantitative operating decisions, improve quality and flow, and align execution with strategy.',
  data = $omjson${"slug": "operations-management", "title": "Operations Management", "description": "This syllabus is designed for a one-semester Operations Management course for business and supply-chain students. It develops the ability to diagnose processes, make quantitative operating decisions, improve quality and flow, and align execution with strategy.", "topics": [{"id": "951b0dd9-6aa5-45b5-8e18-58cf530534d8", "type": "topic", "title": "Course Orientation, Operations Strategy, and Competitive Priorities", "description": "This opening unit explains operations as the system that turns resources into customer value. Students learn how operating choices support strategy and create tradeoffs among cost, quality, speed, flexibility, and dependability.", "children": [{"id": "bf82c55d-960e-4901-9e69-0cab6ff2e071", "type": "subtopic", "title": "The Role of Operations", "children": [{"id": "9ef5f0bc-5115-4265-93c9-6bbf53bb8adb", "type": "concept", "title": "Inputs, transformation processes, outputs"}, {"id": "a9caf8b3-eb0d-46ab-b959-4545c2291ea8", "type": "concept", "title": "Manufacturing versus service operations"}, {"id": "5b13c7c5-9608-4ebf-b36a-39ca0d48f9d2", "type": "concept", "title": "Front-office and back-office activities"}], "description": "Students learn why operations matters in manufacturing, services, nonprofit organizations, and digital businesses."}, {"id": "1c5e42d7-f930-4ac3-a4f8-4c7b28546f0d", "type": "subtopic", "title": "Competitive Priorities", "children": [{"id": "ee1ed1c7-d08c-41ad-9df5-32344bc20d1c", "type": "concept", "title": "Cost, quality, delivery, flexibility, innovation"}, {"id": "911e656a-e132-4291-b7cf-78d1fd4c3f4c", "type": "concept", "title": "Order winners and qualifiers"}, {"id": "bf95cc0b-a00f-4472-8490-798d17d1ec0b", "type": "concept", "title": "Tradeoffs and cumulative capabilities"}], "description": "Students learn the dimensions on which operations can compete."}, {"id": "57ba11c5-9cd3-4b6e-83ec-380df06d3003", "type": "subtopic", "title": "Operations Strategy", "children": [{"id": "c0ed34b2-91a6-4864-8293-2907aaf9d1fa", "type": "concept", "title": "Process, capacity, technology, and supply-network decisions"}, {"id": "0abf94cc-9f1c-4616-a789-09e07781e2fb", "type": "concept", "title": "Alignment with customer value proposition"}, {"id": "0e9969f4-57f8-4bdf-8ce6-e4fbf3915d19", "type": "concept", "title": "Performance metrics and strategic fit"}], "description": "Students connect long-term operating choices to business strategy."}]}, {"id": "49b84a1b-488f-48e9-b6cd-afacb3e87cb0", "type": "topic", "title": "Process Analysis, Flow, Bottlenecks, and Productivity", "description": "This unit gives students the core diagnostic tools of operations management. They learn to see work as a flow system and identify what limits performance.", "children": [{"id": "0afa2c92-11af-4a48-8e4d-b80c6a0a4d7c", "type": "subtopic", "title": "Process Mapping", "children": [{"id": "2c9dcc7d-59cb-4421-b080-13137eea18c6", "type": "concept", "title": "Process flow diagrams"}, {"id": "e5eaba51-6e23-4b0f-9cc8-7f8bde005bb0", "type": "concept", "title": "Activities, decisions, buffers, and handoffs"}, {"id": "c8153993-2c95-4bdd-99e7-02f9285ccb12", "type": "concept", "title": "Value-added and non-value-added work"}], "description": "Students learn to make invisible workflows visible."}, {"id": "63082a3a-5e35-49d2-bf11-224ff65f53f3", "type": "subtopic", "title": "Flow Measures and Bottlenecks", "children": [{"id": "9aa8017f-dcb5-4e6f-aa8f-7dbc27b7314e", "type": "concept", "title": "Flow rate, flow time, inventory"}, {"id": "c9f98727-bba7-4dfa-a331-a6b61e290cd2", "type": "concept", "title": "Little's Law"}, {"id": "5776f163-e8c0-4f98-945d-3c095110d26d", "type": "concept", "title": "Bottleneck capacity and utilization"}], "description": "Students quantify how work moves through a process."}, {"id": "00c1917f-cfef-468f-b503-e0190f8e7cc4", "type": "subtopic", "title": "Productivity and Improvement", "children": [{"id": "49ac9d84-b6b2-4d35-87af-8377a3e3e3f4", "type": "concept", "title": "Labor and multifactor productivity"}, {"id": "9d78f531-f2ff-4d7f-8aee-5590fa6dac68", "type": "concept", "title": "Throughput and cycle time"}, {"id": "34ad0a32-c9fd-4705-bb1b-0ab7367830f6", "type": "concept", "title": "Constraint-focused improvement"}], "description": "Students learn to measure output relative to resources and prioritize improvement."}]}, {"id": "963948db-2554-47b6-b435-d8ad94e77ef6", "type": "topic", "title": "Process Design, Service Operations, and Customer Experience", "description": "Process design determines how reliably and efficiently an organization delivers value. This unit compares process structures and highlights the special challenges of services.", "children": [{"id": "86e9e212-61f4-4f40-9bfc-e26f8d360974", "type": "subtopic", "title": "Process Types and Choice", "children": [{"id": "f8a28ef2-c177-4128-95e5-3eef839f227c", "type": "concept", "title": "Project, job shop, batch, line, continuous flow"}, {"id": "ed074184-8caf-4598-9725-2979a5eeaebd", "type": "concept", "title": "Product-process matrix"}, {"id": "96766346-8d3d-4b8b-a076-46a4a8cf1ae9", "type": "concept", "title": "Standardization versus customization"}], "description": "Students learn how volume, variety, and customization shape process design."}, {"id": "9d48b5e7-35a3-499e-bbf4-e98f6d690c9b", "type": "subtopic", "title": "Service Process Design", "children": [{"id": "44cbe5ea-ba20-413f-9cd4-e5ed95ddefe8", "type": "concept", "title": "Customer contact"}, {"id": "abd2061a-b292-455b-a91d-36738ba64578", "type": "concept", "title": "Service blueprinting"}, {"id": "66eb4f59-99ef-4c20-a681-2a4cc1cf1f78", "type": "concept", "title": "Frontstage and backstage design"}], "description": "Services often involve customer presence and variability."}, {"id": "34d12563-3bfa-4e6c-a1e3-fff73e8add2c", "type": "subtopic", "title": "Customer Experience and Failure Recovery", "children": [{"id": "999fe424-4858-48da-ac1f-ee357c62310d", "type": "concept", "title": "Waiting, handoffs, and information"}, {"id": "2e6cc13f-2793-4cd7-8bf8-c1e3ef1540cb", "type": "concept", "title": "Service failures and recovery"}, {"id": "a278a2f6-d95c-4c25-b997-ee5b583974f8", "type": "concept", "title": "Poka-yoke for services"}], "description": "Students connect operational design to perceived service quality."}]}, {"id": "8b84fa45-e742-4b19-8b21-5887b2ce36b4", "type": "topic", "title": "Capacity Planning, Queueing, and Wait-Time Management", "description": "Capacity decisions determine whether operations can meet demand without excessive cost or delay. Students learn both long-term planning and short-term queue behavior.", "children": [{"id": "625d0dbb-a13e-4553-898d-5ceef27c8544", "type": "subtopic", "title": "Capacity Concepts", "children": [{"id": "9217cf04-036e-47a2-beeb-68331d523a9a", "type": "concept", "title": "Design capacity and effective capacity"}, {"id": "1cbf2bdc-3a1a-415b-9bdc-20b5a8ac2c47", "type": "concept", "title": "Utilization and efficiency"}, {"id": "b5102138-e211-4e61-84e6-ba713f5d9afe", "type": "concept", "title": "Capacity cushion"}], "description": "Students distinguish theoretical capacity from what is realistically available."}, {"id": "3049fe41-1800-4d62-8220-d95a0ba38065", "type": "subtopic", "title": "Bottleneck and Capacity Analysis", "children": [{"id": "83b577a8-d80f-4203-b1e7-44a28db12fd9", "type": "concept", "title": "Resource-level capacity"}, {"id": "6daa19e0-dc57-4b84-aeb7-f0003b852742", "type": "concept", "title": "Product mix and weighted demand"}, {"id": "3dd9f027-96a0-4aee-88c8-f49dd259789c", "type": "concept", "title": "Expanding or balancing capacity"}], "description": "Students learn how capacity changes affect the whole process."}, {"id": "ad20b37b-6302-497d-9395-bd74ddea0821", "type": "subtopic", "title": "Queueing and Wait-Time Design", "children": [{"id": "9d1a5e1c-b38c-4a9f-971e-8829c99aa366", "type": "concept", "title": "Arrival and service rates"}, {"id": "58ccd8f0-eb55-4fd1-a2ad-d84e93705e4f", "type": "concept", "title": "Utilization and waiting-time relationship"}, {"id": "58e5846b-ac9c-445e-b3ce-4a48c5ad1c67", "type": "concept", "title": "Pooling, appointments, triage, and customer psychology"}], "description": "Students learn why variability creates waiting and how managers can respond."}]}, {"id": "f54cc847-feee-4078-988a-69e62df2e5c1", "type": "topic", "title": "Facility Location, Layout, and Network Configuration", "description": "Where facilities are located and how work is arranged shape cost, responsiveness, and customer access. This unit treats location and layout as strategic operating choices.", "children": [{"id": "d4c1277e-07c8-456d-a380-3e099bc6d397", "type": "subtopic", "title": "Location Decisions", "children": [{"id": "b98fd34b-1d5c-4b74-b62b-ca31a079ba1d", "type": "concept", "title": "Labor, customers, suppliers, taxes, risk"}, {"id": "4e0867a9-f781-409b-9e2a-9769babc2c6a", "type": "concept", "title": "Factor-rating and center-of-gravity methods"}, {"id": "59cb51d3-a2e4-4800-888f-269f1699cf28", "type": "concept", "title": "Global versus local considerations"}], "description": "Students learn the factors that drive facility placement."}, {"id": "d99ed7ca-5d5a-4079-89f5-e6c4dcdcb8df", "type": "subtopic", "title": "Layout Types", "children": [{"id": "ddb225c3-84f9-41ba-a856-bf7b6e8e6d2a", "type": "concept", "title": "Process, product, cellular, fixed-position layouts"}, {"id": "79e69c61-7737-479c-a1a3-c7266b6a66e3", "type": "concept", "title": "Retail and office layouts"}, {"id": "93be52ba-1cba-4673-a2e0-809a010d1ce7", "type": "concept", "title": "Flow distance and adjacency"}], "description": "Students compare layouts suited to different process structures."}, {"id": "1451ca75-4f17-4ec6-b7de-e07ac8dfee7d", "type": "subtopic", "title": "Network Configuration", "children": [{"id": "5f9b9cfe-2bb8-47e1-ba02-9d380b02e8b7", "type": "concept", "title": "Centralization versus decentralization"}, {"id": "ac706e9c-8be2-4d32-b8aa-c52fd0a450e9", "type": "concept", "title": "Hub-and-spoke and regional networks"}, {"id": "d0d79fd9-5cd0-47a4-9d82-efa95bfeb821", "type": "concept", "title": "Resilience and responsiveness tradeoffs"}], "description": "Students connect individual sites to broader operating networks."}]}, {"id": "217db238-fd0f-4095-809d-227cf8a953db", "type": "topic", "title": "Demand Forecasting and Sales and Operations Planning", "description": "Forecasting turns uncertain demand into planning inputs. Students learn to evaluate forecasts and use them in cross-functional operating plans.", "children": [{"id": "51d79dbd-958e-4af0-b35d-1c304b8495e1", "type": "subtopic", "title": "Forecasting Foundations", "children": [{"id": "a9067343-a1c2-4283-9d34-a4b12d3e091b", "type": "concept", "title": "Forecast horizon and level of aggregation"}, {"id": "060654a2-f47b-4e5e-97e8-5086957055a4", "type": "concept", "title": "Qualitative and quantitative methods"}, {"id": "f87ce984-fc7b-44cc-8f1e-9faa36b2022d", "type": "concept", "title": "Bias, uncertainty, and forecast error"}], "description": "Students learn what forecasts can and cannot do."}, {"id": "50174d3d-8a29-442c-bf77-12f40b98263b", "type": "subtopic", "title": "Time-Series Methods", "children": [{"id": "f6a9cdfd-6911-4f4b-b504-3669792e8f45", "type": "concept", "title": "Moving averages"}, {"id": "c9eeca18-aa2a-4656-a755-e693c318b062", "type": "concept", "title": "Exponential smoothing"}, {"id": "4472b07a-ee0e-45d2-8421-8d48963e5185", "type": "concept", "title": "Trend and seasonality overview"}], "description": "Students practice common methods for stable and trending demand."}, {"id": "2051ab51-5033-41e3-90b9-feec55986c72", "type": "subtopic", "title": "Sales and Operations Planning", "children": [{"id": "f51a2d44-c0ad-439c-89be-c47fb2596842", "type": "concept", "title": "Consensus demand plan"}, {"id": "bc5444b6-1db2-4357-98f8-15c2630ebad9", "type": "concept", "title": "Supply-demand balancing"}, {"id": "498fa203-30eb-4689-84dc-f86490d5779e", "type": "concept", "title": "Scenario planning and executive decisions"}], "description": "Students connect demand forecasts to capacity, inventory, workforce, and finance."}]}, {"id": "d3f9a5c1-7a40-47d6-bb9d-b301e26a9055", "type": "topic", "title": "Inventory Management, EOQ, Safety Stock, and Service Levels", "description": "Inventory buffers uncertainty but ties up cash and can hide problems. Students learn how to balance availability, cost, and risk.", "children": [{"id": "9a0682ff-e3cf-4101-acff-8020efde3166", "type": "subtopic", "title": "Why Inventory Exists", "children": [{"id": "d639d83d-8f04-466f-9982-2ee4c59fceb0", "type": "concept", "title": "Cycle, safety, anticipation, and pipeline inventory"}, {"id": "aeeb277b-d635-40e0-a148-b6dd8436e772", "type": "concept", "title": "Holding, ordering, shortage, and obsolescence costs"}, {"id": "33755f90-d11c-4c19-a212-fdbf45f96943", "type": "concept", "title": "ABC classification"}], "description": "Students learn the roles and costs of inventory."}, {"id": "61ab5c53-16ac-4464-af58-f851d2adb445", "type": "subtopic", "title": "EOQ and Reorder Decisions", "children": [{"id": "962f0e15-814e-4544-8d26-297ecc70dd52", "type": "concept", "title": "Economic order quantity"}, {"id": "12185869-e383-4ae8-ac17-109842d20508", "type": "concept", "title": "Reorder point"}, {"id": "9c4b3b2c-528d-42fb-817a-be5cd401b2b2", "type": "concept", "title": "Continuous and periodic review"}], "description": "Students use basic models to set order quantities and timing."}, {"id": "8834695a-1d36-40e4-8006-74ba995ce588", "type": "subtopic", "title": "Safety Stock and Service Levels", "children": [{"id": "c2f15fb7-9932-4be8-a37d-d9505e61203c", "type": "concept", "title": "Demand and lead-time uncertainty"}, {"id": "b82f6c2e-7da7-468f-ac0b-9a38fa705df3", "type": "concept", "title": "Cycle service level and fill rate"}, {"id": "8278d808-005d-4d26-81e4-1bed1b89654d", "type": "concept", "title": "Risk pooling"}], "description": "Students learn how variability drives buffer requirements."}]}, {"id": "a1d1747d-41fe-4fe0-bcb9-6dafa8df5a61", "type": "topic", "title": "Aggregate Planning, MRP, Scheduling, and Operations Control", "description": "This unit moves from medium-term plans to day-to-day execution. Students learn how organizations coordinate demand, materials, labor, and timing.", "children": [{"id": "f55c967b-3d17-46c7-aea9-cfc14fd47504", "type": "subtopic", "title": "Aggregate Planning", "children": [{"id": "46a225c6-53f5-45fc-b9e6-869f003ac9fb", "type": "concept", "title": "Level, chase, and mixed strategies"}, {"id": "de2a0819-f307-4f7e-b050-34884da66eaa", "type": "concept", "title": "Workforce, overtime, subcontracting, and inventory"}, {"id": "eff4eeae-7c14-4800-bf83-b3fb97b07344", "type": "concept", "title": "Cost tradeoffs"}], "description": "Students learn to balance capacity and demand over a planning horizon."}, {"id": "2681a8c8-af8a-44ef-98e4-568b976b2295", "type": "subtopic", "title": "Material Requirements Planning", "children": [{"id": "740230cd-a70d-4447-933a-58b91705f520", "type": "concept", "title": "Master production schedule"}, {"id": "2f1b4c62-afac-461f-895d-d3b06e8c0026", "type": "concept", "title": "Bills of materials"}, {"id": "0113e2a4-07bb-4fca-b2f8-40d8d6d23daf", "type": "concept", "title": "Lead times, lot sizing, and planned orders"}], "description": "MRP translates finished-goods plans into component needs."}, {"id": "3eaf2cc0-ad4b-4c18-81c1-23f65275dfad", "type": "subtopic", "title": "Scheduling and Control", "children": [{"id": "5dcd2ecd-df78-48b5-8459-efb26195302b", "type": "concept", "title": "Priority rules"}, {"id": "4a6281ee-017e-43de-b232-a6913f62bdb3", "type": "concept", "title": "Gantt charts and finite capacity"}, {"id": "4de3c87c-d184-4234-b2fe-beb7c5314b61", "type": "concept", "title": "ERP and shop-floor control overview"}], "description": "Students learn how sequencing and monitoring affect delivery performance."}]}, {"id": "b780e196-bf2a-4243-b92b-3d715b6b018b", "type": "topic", "title": "Quality Management, Statistical Process Control, and Six Sigma", "description": "Quality is designed and managed, not inspected in at the end. This unit teaches prevention, measurement, process stability, and structured problem solving.", "children": [{"id": "5e358747-723f-4604-9b9f-12fc4d0b68dd", "type": "subtopic", "title": "Quality Concepts and TQM", "children": [{"id": "9e3b34e0-0d21-4442-8cd4-abcb4997fb83", "type": "concept", "title": "Fitness for use and conformance"}, {"id": "002a13ca-46cd-4c2a-91af-197e7fa19f8f", "type": "concept", "title": "Cost of quality"}, {"id": "927b2840-9998-4f77-b09d-39da375a6f61", "type": "concept", "title": "Customer focus and continuous improvement"}], "description": "Students learn how quality affects customers, cost, and strategy."}, {"id": "cbe11c97-30e4-42a0-aaf0-44a854578ffe", "type": "subtopic", "title": "Statistical Process Control", "children": [{"id": "c8f97b3b-192d-4988-af18-a412aae74fc6", "type": "concept", "title": "Control charts"}, {"id": "edf35e10-52db-4d8f-883e-9849c9acec08", "type": "concept", "title": "Process stability"}, {"id": "b649ecb2-475c-49ec-b0e3-57b0e21258e7", "type": "concept", "title": "Process capability overview"}], "description": "Students distinguish common-cause variation from special-cause variation."}, {"id": "4575289e-1178-424e-8b81-58fd2196ea67", "type": "subtopic", "title": "Six Sigma and Root-Cause Analysis", "children": [{"id": "937984c5-7ae7-4743-9bd8-3fc5817f9fa4", "type": "concept", "title": "DMAIC"}, {"id": "9952b2e7-b9a0-448b-a317-ba261f9088e7", "type": "concept", "title": "Pareto charts, fishbone diagrams, 5 Whys"}, {"id": "609dd3b2-3f25-4d4d-b12c-2f50954867d5", "type": "concept", "title": "Defects, yield, and capability"}], "description": "Students learn structured methods for reducing defects and variation."}]}, {"id": "5d8f2d58-cfd5-43fb-87ab-f0e6fff70d59", "type": "topic", "title": "Lean Operations, Just-in-Time, and Continuous Improvement", "description": "Lean focuses on creating smooth flow with less waste. Students learn how systems, people, and problem solving work together.", "children": [{"id": "06c24117-8e8e-4e79-93c7-38c9d7d6afaf", "type": "subtopic", "title": "Lean Principles and Waste", "children": [{"id": "3d083fa5-a99d-4d75-bf63-184df0003948", "type": "concept", "title": "Value and value stream"}, {"id": "88b39fa8-850d-4bdb-8eac-5c0c1705efc2", "type": "concept", "title": "Eight wastes"}, {"id": "bbddc38c-e7ed-443c-8b46-73739be967c2", "type": "concept", "title": "Flow and pull"}], "description": "Students learn to identify activities that consume resources without creating customer value."}, {"id": "93f8770d-1481-4319-ae4f-ef30b75645d5", "type": "subtopic", "title": "Just-in-Time Systems", "children": [{"id": "b26fdd0f-da45-4c1a-89d2-84f0e4d7ad07", "type": "concept", "title": "Kanban and pull systems"}, {"id": "330f513c-8ee6-4413-9051-9888c0944eac", "type": "concept", "title": "Small lots and setup reduction"}, {"id": "d3843055-91b8-418c-aa0b-b089cd31bec9", "type": "concept", "title": "Supplier coordination"}], "description": "Students learn how small buffers and reliable processes support responsive operations."}, {"id": "4bd5de2e-ca60-47c9-b8a4-354f9cec0dc2", "type": "subtopic", "title": "Continuous Improvement Culture", "children": [{"id": "91e2e55d-391b-410d-b15a-f9947963aa1a", "type": "concept", "title": "Kaizen"}, {"id": "2313a4e5-1ad5-4a60-abfa-3436a4cf9283", "type": "concept", "title": "Standard work"}, {"id": "08049fbf-5f02-4c4f-ba67-fd179d1294a8", "type": "concept", "title": "Visual management and daily problem solving"}], "description": "Lean depends on routines for learning and employee involvement."}]}, {"id": "7869621d-b797-464b-8273-7f23a9051c56", "type": "topic", "title": "Project Management, CPM, PERT, and Resource Coordination", "description": "Projects are temporary operations with interdependent tasks. Students learn to plan schedules, identify critical work, and manage uncertainty.", "children": [{"id": "35151f4a-9644-4400-a9a2-b74f6e7b257c", "type": "subtopic", "title": "Project Planning", "children": [{"id": "e3251383-beae-4737-809e-6604592bf811", "type": "concept", "title": "Scope and objectives"}, {"id": "ebe23e8f-ede0-40f7-a384-4cc18d578a3c", "type": "concept", "title": "Work breakdown structure"}, {"id": "d9e1badc-b62d-49b0-b74e-3939ad19f659", "type": "concept", "title": "Milestones and responsibility"}], "description": "Students learn to define deliverables and decompose work."}, {"id": "91a97a4b-0725-41ee-8508-cbd4798dabb0", "type": "subtopic", "title": "Network Scheduling", "children": [{"id": "c221d813-e8c9-44a7-83f8-143734b643d2", "type": "concept", "title": "Activity networks"}, {"id": "9cec37f3-4f76-4deb-a91b-4400831375d2", "type": "concept", "title": "Critical path method"}, {"id": "73019d23-7d43-4eb5-bbb8-866f74d2c1cc", "type": "concept", "title": "Slack and crashing"}], "description": "Students calculate project timing and identify schedule risk."}, {"id": "53221fa8-443b-4225-a6b3-15d7c4844543", "type": "subtopic", "title": "PERT and Resource Coordination", "children": [{"id": "4af1a57e-654b-46d0-9695-6b7ea5262b8c", "type": "concept", "title": "Optimistic, most likely, pessimistic times"}, {"id": "4e951091-d3ea-43fc-96fe-06df6255f824", "type": "concept", "title": "Expected time and variance"}, {"id": "190abc3d-cb9d-430a-a050-16c6d8d1506b", "type": "concept", "title": "Resource leveling and monitoring"}], "description": "Students account for uncertainty and constrained resources."}]}, {"id": "b51d77b4-da06-40f3-b4bd-cab13dfabb3d", "type": "topic", "title": "Supply Chain Fundamentals, Sourcing, Logistics, and Coordination", "description": "Operations extends beyond a single organization. This unit introduces the network of suppliers, facilities, logistics providers, and customers that jointly deliver value.", "children": [{"id": "06df2919-7b37-466f-a551-dd23c90d5144", "type": "subtopic", "title": "Supply Chain Structure", "children": [{"id": "9b878f84-bec8-42be-9373-fbdaa3482da9", "type": "concept", "title": "Suppliers, manufacturers, distributors, customers"}, {"id": "ed08caa3-58ba-4c2f-89ad-6b785f0ae18f", "type": "concept", "title": "Upstream and downstream flows"}, {"id": "5d355c86-ad46-4430-83b1-36b7a68defed", "type": "concept", "title": "Push, pull, and decoupling points"}], "description": "Students learn how material, information, and cash flow across organizations."}, {"id": "540ff830-5941-47fc-8773-d28e41cb059b", "type": "subtopic", "title": "Sourcing and Supplier Management", "children": [{"id": "4ca0498e-0f40-456a-ba0e-68b5a1084d8a", "type": "concept", "title": "Make-or-buy"}, {"id": "4e3d43ff-22ae-4b66-8c85-f6d07f93aa33", "type": "concept", "title": "Supplier selection and total cost"}, {"id": "921ffec5-528d-4ba5-88c0-18b53c2a0433", "type": "concept", "title": "Supplier quality and relationships"}], "description": "Students learn how procurement choices affect cost, quality, risk, and innovation."}, {"id": "bd222e3a-d6af-43d7-a784-d6502e3d10ad", "type": "subtopic", "title": "Logistics and Coordination", "children": [{"id": "1896eb86-9ff3-4367-a826-7f23258b1b39", "type": "concept", "title": "Transportation modes"}, {"id": "668b2e55-09ba-41b8-8715-8693197d5da3", "type": "concept", "title": "Warehousing and distribution"}, {"id": "bc2ff7fb-bf35-4331-8273-15cfedb1279b", "type": "concept", "title": "Bullwhip effect and coordination"}], "description": "Students learn how transportation, warehousing, and information shape service."}]}, {"id": "a77b457b-f8eb-49ee-817a-ee928f788479", "type": "topic", "title": "Operational Resilience, Risk, Sustainability, and Ethical Operations", "description": "Modern operations must perform under disruption while respecting environmental and social responsibilities. Students learn to build systems that recover, adapt, and create durable value.", "children": [{"id": "98e98b07-d113-41d1-ac90-ff632ffe555a", "type": "subtopic", "title": "Operational Risk and Resilience", "children": [{"id": "0b863b59-de6a-4ed8-98be-24229fd4f8ce", "type": "concept", "title": "Disruption sources"}, {"id": "40688b0f-1e8f-4a7e-a957-20c987baf4c9", "type": "concept", "title": "Redundancy, flexibility, and visibility"}, {"id": "6e3b82bb-956c-4ec9-8564-9c00645ac57d", "type": "concept", "title": "Business continuity and recovery"}], "description": "Students learn to identify vulnerabilities and prepare responses."}, {"id": "56ed9e5e-d768-4f78-9273-4412896865eb", "type": "subtopic", "title": "Sustainable Operations", "children": [{"id": "cb10acb9-114d-4c11-b62a-db147fe7464e", "type": "concept", "title": "Waste, energy, emissions, and circularity"}, {"id": "7def43e5-fd8e-48f4-b273-00f06c1287f7", "type": "concept", "title": "Life-cycle thinking"}, {"id": "b0a91f6a-558c-4d35-a763-8fdcadcc0f99", "type": "concept", "title": "Sustainable sourcing"}], "description": "Students connect operational choices to environmental performance."}, {"id": "f64244bb-d1a5-4c0e-b7dc-a0ee39062634", "type": "subtopic", "title": "Ethics and Responsible Operations", "children": [{"id": "226d54b8-9054-41f7-a3e9-8d2d31ab19ac", "type": "concept", "title": "Worker safety and labor standards"}, {"id": "ec37336f-904b-47e2-b735-aef5d0dd5dc7", "type": "concept", "title": "Supplier responsibility"}, {"id": "8504bb09-ae3e-4db5-bd31-44f27955679d", "type": "concept", "title": "Transparency and stakeholder tradeoffs"}], "description": "Students examine the human consequences of operating decisions."}]}, {"id": "78ebf33f-3dc9-4ddd-8634-8ea0fcc6dbee", "type": "topic", "title": "Technology, Analytics, Automation, and Integrated Operations Applications", "description": "The final unit examines how data and technology change operating decisions. Students integrate course tools through realistic cases and analytics-enabled improvement.", "children": [{"id": "71a8dbef-1402-4585-ab95-dac8646e00fc", "type": "subtopic", "title": "Digital Operations Technology", "childr